// Normalise the MESSAGES_UPSERT payload down to the metadata the CRM needs.
// Evolution API (S3_ENABLED=true) has already written the file to MinIO by this point,
// so we forward only the object reference — never the bytes. This is what makes 200MB
// files work: the payload below is ~1KB regardless of file size.

const out = [];

for (const item of $input.all()) {
  const data = item.json.body?.data ?? item.json.data ?? {};
  const message = data.message ?? {};
  const key = data.key ?? {};

  // The media object lives under a type-specific key; whichever is present is ours.
  const media =
    message.documentMessage ||
    message.imageMessage ||
    message.videoMessage ||
    message.audioMessage ||
    message.stickerMessage ||
    message.documentWithCaptionMessage?.message?.documentMessage ||
    {};

  // Evolution has moved mediaUrl between these spots across versions — take the first hit.
  // Deliberately NOT falling back to media.url: that is WhatsApp's own CDN URL and its bytes
  // are encrypted, so using it would turn "S3 is off" into a confusing 404 from the CRM.
  const mediaUrl = data.mediaUrl || message.mediaUrl || null;

  if (!mediaUrl) {
    throw new Error(
      'No mediaUrl in the webhook payload. Check that S3_ENABLED=true on Evolution API and ' +
      'that it can reach MinIO — without it the file is never written to storage. ' +
      'messageType=' + (data.messageType || 'unknown')
    );
  }

  const fileName =
    media.fileName ||
    media.caption ||
    `${data.messageType || 'media'}_${key.id || Date.now()}`;

  out.push({
    json: {
      groupId: key.remoteJid || '',
      sender: key.participant || key.remoteJid || '',
      messageId: key.id || '',
      fileName,
      mimeType: media.mimetype || 'application/octet-stream',
      size: Number(media.fileLength) || null,
      mediaUrl,
    },
  });
}

return out;
